INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Pixelbild bei Vergrößerung immer scharf bleibt?', 2, '[{"text": "Nein", "correct": true, "because": "Pixel werden sichtbar, Bild wird unscharf"}, {"text": "Ja", "correct": false, "because": "Begrenzte Auflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format eignet sich am besten für Fotos mit vielen Farben?', 3, '[{"text": "JPEG", "correct": true, "because": "Gute Kompression bei hoher Farbtiefe"}, {"text": "GIF", "correct": false, "because": "Begrenzte Farben"}, {"text": "BMP", "correct": false, "because": "Unkomprimiert, große Dateien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Pixelbild flexibel?', 4, '[{"text": "Hohe Auflösung", "correct": true, "because": "Mehr Details bei Skalierung"}, {"text": "Farbmodell", "correct": true, "because": "Ermöglicht Bearbeitung"}, {"text": "Vektordaten", "correct": false, "because": "Nur bei Vektorgrafiken"}, {"text": "Festes Seitenverhältnis", "correct": false, "because": "Einschränkt Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PNG unterstützt Transparenz. b) Es ist verlustbehaftet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PNG ist verlustfrei"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Bildformats?', 3, '[{"text": "Kompressionsart", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Dateigröße", "correct": false, "because": "Wichtig für Speicher"}, {"text": "Druckertyp", "correct": true, "because": "Nicht primär für digitale Bilder"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Pixelbild unendlich skalierbar ist?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzte Pixelanzahl"}, {"text": "Ja", "correct": false, "because": "Nur Vektorgrafiken skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Farbmodell nutze ich für digitale Bildschirme?', 4, '[{"text": "RGB", "correct": true, "because": "Additive Farbmischung für Bildschirme"}, {"text": "CMYK", "correct": false, "because": "Für Druck geeignet"}, {"text": "HSV", "correct": false, "because": "Für Bearbeitung, nicht Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Dateigröße eines Bildes?', 5, '[{"text": "Auflösung", "correct": true, "because": "Mehr Pixel, mehr Daten"}, {"text": "Kompression", "correct": true, "because": "Reduziert Datenmenge"}, {"text": "Dateiname", "correct": false, "because": "Kein Einfluss auf Größe"}, {"text": "Bildinhalt", "correct": false, "because": "Indirekt über Kompression"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) JPEG ist verlustbehaftet. b) Es unterstützt Transparenz. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "JPEG hat keine Transparenz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Bearbeitung eines Pixelbildes?', 3, '[{"text": "Bildeditor", "correct": false, "because": "Notwendig für Anpassungen"}, {"text": "Farbtiefe", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "3D-Modellierungssoftware", "correct": true, "because": "Für 3D, nicht 2D"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist GIF für hochauflösende Fotos geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzte Farbtiefe"}, {"text": "Ja", "correct": false, "because": "Besser für Animationen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für verlustfreie Kompression?', 4, '[{"text": "PNG", "correct": true, "because": "Behält alle Daten"}, {"text": "JPEG", "correct": false, "because": "Verlustbehaftet"}, {"text": "GIF", "correct": false, "because": "Begrenzte Farben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Pixelbilder für Druck ungeeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mit hoher Auflösung druckbar"}, {"text": "Ja", "correct": false, "because": "Auflösung entscheidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Optimierung eines Bildes fürs Web?', 3, '[{"text": "Kleine Dateigröße", "correct": true, "because": "Schnellere Ladezeiten"}, {"text": "Maximale Auflösung", "correct": false, "because": "Erhöht Ladezeit"}, {"text": "Komplexe Farben", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pixelbilder nutzen Raster. b) Sie sind immer kleiner als Vektorgrafiken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Auflösung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Pixelbild für Fotobearbeitung?', 5, '[{"text": "Detaillierte Bearbeitung", "correct": true, "because": "Pixelgenaue Anpassung"}, {"text": "Breite Softwareunterstützung", "correct": true, "because": "Viele Editoren kompatibel"}, {"text": "Unendliche Skalierung", "correct": false, "because": "Nur bei Vektoren"}, {"text": "Geringer Speicherbedarf", "correct": false, "because": "Hängt von Auflösung ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Speicherung eines Bildes unwichtig?', 3, '[{"text": "Auflösung", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Format", "correct": false, "because": "Bestimmt Kompression"}, {"text": "Dateierstellungsdatum", "correct": true, "because": "Kein Einfluss auf Bild"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt jedes Pixelbild RGB?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Modelle wie CMYK möglich"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Pixelbilder für Animationen optimal sind?', 3, '[{"text": "Nein", "correct": true, "because": "GIF begrenzt, Vektoren flexibler"}, {"text": "Ja", "correct": false, "because": "Eingeschränkte Skalierbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Bild für schnelles Laden optimiere?', 4, '[{"text": "JPEG mit hoher Kompression", "correct": true, "because": "Reduziert Dateigröße"}, {"text": "PNG ohne Kompression", "correct": false, "because": "Größere Dateien"}, {"text": "BMP verwenden", "correct": false, "because": "Unkomprimiert, groß"}]');
